changeSet.sql:
ALTER TABLE transaction.transactions
    ALTER COLUMN status TYPE VARCHAR(25);

ALTER TABLE transaction.transactions
    DROP CONSTRAINT IF EXISTS chk_transaction_status;

ALTER TABLE transaction.transactions
    ADD CONSTRAINT chk_transaction_status
        CHECK (status IN ('PENDING', 'DEBITED', 'COMPLETED', 'FAILED', 'CANCELLED', 'COMPENSATION_PENDING'));

CREATE UNIQUE INDEX IF NOT EXISTS idx_transactions_transfer_account
    ON transaction.transactions (transfer_id, account_id)
    WHERE transfer_id IS NOT NULL;
